--
-- Create procedure `sp_update_package`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_update_package (IN p_id int,
IN p_name varchar(100),
IN p_description text,
IN p_days int,
IN p_price decimal(10, 2),
IN p_features json,
IN p_is_popular boolean)
BEGIN
  UPDATE packages
  SET name = p_name,
      description = p_description,
      days = p_days,
      price = p_price,
      features = p_features,
      is_popular = p_is_popular,
      updated_at = CURRENT_TIMESTAMP
  WHERE id = p_id;

  -- Return 1 if the row was updated, 0 otherwise
  SELECT
    ROW_COUNT() AS updated_rows;
END
$$

--
-- Create procedure `sp_get_popular_packages`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_get_popular_packages ()
BEGIN
  SELECT
    id,
    name,
    description,
    days,
    price,
    features,
    is_popular,
    created_at,
    updated_at
  FROM packages
  WHERE is_popular = 1
  ORDER BY price ASC;
END
$$

