--
-- Create procedure `sp_create_package`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_create_package (IN p_name varchar(100),
IN p_description text,
IN p_days int,
IN p_price decimal(10, 2),
IN p_features json,
IN p_is_popular boolean)
BEGIN
  INSERT INTO packages (name,
  description,
  days,
  price,
  features,
  is_popular)
    VALUES (p_name, p_description, p_days, p_price, p_features, p_is_popular);

  -- Return the newly created package
  SELECT
    LAST_INSERT_ID() AS id;
END
$$

