DELIMITER $$

--
-- Create procedure `sp_get_packages_with_subscriptions_count`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_get_packages_with_subscriptions_count ()
BEGIN
  SELECT
    p.id,
    p.name,
    p.description,
    p.days,
    p.price,
    p.features,
    p.is_popular,
    COUNT(s.id) AS active_subscriptions,
    p.created_at,
    p.updated_at
  FROM packages p
    LEFT JOIN subscriptions s
      ON p.id = s.package_id
      AND s.status = 'active'
  GROUP BY p.id
  ORDER BY active_subscriptions DESC, p.name ASC;
END
$$

--
-- Create procedure `sp_delete_package`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_delete_package (IN p_id int)
BEGIN
  -- First check if the package has any subscriptions
  DECLARE subscription_count int;

  SELECT
    COUNT(*) INTO subscription_count
  FROM subscriptions
  WHERE package_id = p_id;

  -- Only delete if there are no subscriptions
  IF subscription_count = 0 THEN
    DELETE
      FROM packages
    WHERE id = p_id;
    SELECT
      ROW_COUNT() AS deleted_rows;
  ELSE
    -- Return 0 to indicate no rows were deleted
    SELECT
      0 AS deleted_rows,
      'Package has subscriptions and cannot be deleted' AS message;
  END IF;
END
$$

DELIMITER ;

